/**
 * Check if a given object implements the AdvancedRequestValue interface.
 */
export function instanceOfAdvancedRequestValue(value) {
    return true;
}
export function AdvancedRequestValueFromJSON(json) {
    return AdvancedRequestValueFromJSONTyped(json, false);
}
export function AdvancedRequestValueFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        url: json["url"] == null ? undefined : json["url"],
    };
}
export function AdvancedRequestValueToJSON(json) {
    return AdvancedRequestValueToJSONTyped(json, false);
}
export function AdvancedRequestValueToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        url: value["url"],
    };
}
